import { expect, type Page } from "@playwright/test";

const LARGE_SCREEN_MEDIA = "(min-width: 1536px)";

export const getLocators = (page: Page) => ({
  toggleButton: page.getByTestId("show-button"),
  menu: page.getByRole("menu"),
  allOption: page.getByTestId("view-menu-all"),
  activeFlowOption: page.getByTestId("view-menu-active-flow"),
  historyOption: page.getByTestId("view-menu-flow-history"),
  memoryOption: page.getByTestId("view-menu-memory"),
  sidePanel: page.getByTestId("inspector-side-panel"),
});

const isMenuOpen = async (locators: ReturnType<typeof getLocators>) => locators.menu.isVisible();

const openMenuIfClosed = async (locators: ReturnType<typeof getLocators>) => {
  if (!(await isMenuOpen(locators))) {
    await locators.toggleButton.click();
    await expect(locators.menu, "Inspector view menu should be open").toBeVisible();
  }
};

const closeMenuIfOpen = async (page: Page, locators: ReturnType<typeof getLocators>) => {
  if (await isMenuOpen(locators)) {
    await page.keyboard.press("Escape");
    await expect(locators.menu, "Inspector view menu should close").toBeHidden();
  }
};

export const actions = (page: Page) => {
  const locators = getLocators(page);

  return {
    closeIfOpen: async () => {
      await closeMenuIfOpen(page, locators);
    },
    open: async () => {
      await openMenuIfClosed(locators);
    },
    // Viewport changes add/remove menu items while the popover can stay open; close,
    // wait for matchMedia + React to settle, then reopen for fresh menu content.
    reopenAfterViewportChange: async (expectLargeScreen: boolean) => {
      await closeMenuIfOpen(page, locators);
      await expect
        .poll(
          async () =>
            page.evaluate(([query, expected]) => window.matchMedia(query).matches === expected, [
              LARGE_SCREEN_MEDIA,
              expectLargeScreen,
            ] as const),
          {
            message: `Viewport should match large-screen breakpoint=${expectLargeScreen}`,
          },
        )
        .toBe(true);
      await locators.toggleButton.click();
      await expect(locators.menu, "Inspector view menu should reopen").toBeVisible();
    },
    switchToAll: async () => {
      await openMenuIfClosed(locators);
      await locators.allOption.click();
    },
    switchToActiveFlow: async () => {
      await openMenuIfClosed(locators);
      await locators.activeFlowOption.click();
    },
    switchToHistory: async () => {
      await openMenuIfClosed(locators);
      await locators.historyOption.click();
    },
    switchToMemory: async () => {
      await openMenuIfClosed(locators);
      await locators.memoryOption.click();
    },
  };
};

export const assertions = (page: Page) => {
  const locators = getLocators(page);

  return {
    toggleButtonIsVisible: async () => {
      await expect(
        locators.toggleButton,
        "Inspector view menu toggle should be visible",
      ).toBeVisible();
    },
    activeFlowOptionIsVisible: async () => {
      await expect(
        locators.activeFlowOption,
        "Active Flow option should be visible in the inspector view menu",
      ).toBeVisible();
    },
    historyOptionIsVisible: async () => {
      await expect(
        locators.historyOption,
        "History option should be visible in the inspector view menu",
      ).toBeVisible();
    },
    memoryOptionIsVisible: async () => {
      await expect(
        locators.memoryOption,
        "Memory option should be visible in the inspector view menu",
      ).toBeVisible();
    },
    allOptionIsVisible: async () => {
      await expect(
        locators.allOption,
        "All option should be visible in the inspector view menu",
      ).toBeVisible();
    },
    allOptionIsHidden: async () => {
      await expect(
        locators.allOption,
        "All option should be hidden below the large-screen breakpoint",
      ).toBeHidden();
    },
    sidePanelIsVisible: async () => {
      await expect(
        locators.sidePanel,
        "Inspector side panel should be visible in All layout",
      ).toBeVisible();
    },
  };
};
